#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in movements.log, including SKUs whose net movement is zero.
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3); seen[$1] = 1 }
     END { for (sku in seen) print sku, net[sku] }' \
    movements.log | sort > stock.txt
